	private static TupleExpr normalize(TupleExpr tupleExpr) {
		QueryRoot root = new QueryRoot(tupleExpr);
		new QueryModelNormalizerOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
		return root;
	}

	private static TupleExpr historicalScopedBindQuery(int scenario) {
		// These are the named-context algebra shapes the original tests exercised before the parser retained GRAPH.
		// They remain supported public algebra inputs; this construction makes no claim that an arbitrary GRAPH body
		// may be lowered to them. The unchanged parsed forms have separate retained-boundary and exact-bag controls.
		String subject = scenario < 2 ? "s" : "x";
		TupleExpr argument = namedPattern(subject, "p", "o");
		if (scenario != 2) {
			BindingSetAssignment undef = new BindingSetAssignment();
			undef.setBindingNames(Set.of("x"));
			undef.setBindingSets(List.of(new ListBindingSet(List.of("x"), (Value) null)));
			argument = new Join(undef, argument);
		}
		ValueExpr condition = switch (scenario) {
		case 0 -> new Not(new Bound(Var.of("x")));
		case 1 -> new Not(new Exists(namedPattern("s", "q", "x")));
		case 2 -> new Not(new Exists(namedPattern("x", "q", "z")));
		case 3 -> new Compare(Var.of("o"), new ValueConstant(VF.createIRI("urn:t:z")), Compare.CompareOp.NE);
		default -> throw new AssertionError("Unknown historical algebra fixture " + scenario);
		};
		Extension extension = new Extension(new Filter(argument, condition),
				new ExtensionElem(new ValueConstant(VF.createLiteral("1", CoreDatatype.XSD.INTEGER)), "one"));
		extension.setVariableScopeChange(true);
		Join joined = new Join(values("x", VF.createIRI("urn:t:a"), VF.createIRI("urn:t:b")), extension);
		ProjectionElemList projection = new ProjectionElemList(new ProjectionElem("x"),
				new ProjectionElem(scenario < 2 ? "s" : "o"));
		if (scenario != 1) {
			projection.addElement(new ProjectionElem("one"));
		}
		return new Projection(joined, projection);
	}

	private static StatementPattern namedPattern(String subject, String predicate, String object) {
		return new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of(subject),
				Var.of("_" + predicate, VF.createIRI("urn:t:" + predicate), true, true), Var.of(object),
				Var.of("_graph", VF.createIRI("urn:t:g"), true, true));
	}

	private static TupleExpr projectionArg(TupleExpr root) {
		List<Projection> projections = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Projection node) {
				projections.add(node);
				super.meet(node);
			}
		});
		assertEquals(1, projections.size(), root.toString());
		return projections.get(0).getArg();
	}

	private static Extension scopedExtension(TupleExpr root) {
		List<Extension> extensions = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Extension node) {
				if (node.isVariableScopeChange()) {
					extensions.add(node);
				}
				super.meet(node);
			}
		});
		assertEquals(1, extensions.size(), "expected exactly one scoped BIND\n" + root);
		return extensions.get(0);
	}

	private static BindingSetAssignment values(String name, IRI... values) {
		List<BindingSet> rows = new ArrayList<>();
		for (IRI value : values) {
			rows.add(new ListBindingSet(List.of(name), value));
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(rows);
		return assignment;
	}
